    "market_cap_region_r" INTEGER,
    "market_cap_region_sec_r" INTEGER,
    "market_cap_country_r" INTEGER,
    "market_cap_country_sec_r" INTEGER,
    "er_mean" DOUBLE PRECISION,
    "er_sd" DOUBLE PRECISION,
    "er_p05" DOUBLE PRECISION,
    "er_p50" DOUBLE PRECISION,
    "er_p95" DOUBLE PRECISION,
    "prob_pos" DOUBLE PRECISION,
    "er_mean_terminal" DOUBLE PRECISION,
    "er_sd_terminal" DOUBLE PRECISION,
    "er_p05_terminal" DOUBLE PRECISION,
    "er_p50_terminal" DOUBLE PRECISION,
